//! Filter assembly for transfer + check verbs.
//!
//! Moved from `crates/blit-cli/src/transfers/mod.rs` in A.0.
//! Pre-A.0 the struct had a `from_transfer(&TransferArgs)`
//! constructor — that's now in the CLI as inline field-by-field
//! construction (orphan rule prevents the impl living here:
//! the library can't `impl FilterInputs` for `&TransferArgs` because
//! `TransferArgs` lives in blit-cli). Callers explicitly fill the
//! struct, which is also the shape any front-end's transfer-options
//! modal will use.

use crate::fs_enum::{
    bracket_class_len, exclude_rule, normalize_separators, parse_duration, parse_size,
    typed_exclude_dialect, FileFilter,
};
use eyre::{eyre, Context, Result};
use std::path::{Path, PathBuf};
use std::time::SystemTime;

/// Common shape of the filter inputs across commands. Both
/// `TransferArgs` (copy/mirror/move) and `CheckArgs` (check)
/// populate this with their respective field aliases. The single
/// [`build`] helper consumes it so all commands route through
/// identical filter semantics.
pub struct FilterInputs<'a> {
    pub include: &'a [String],
    pub exclude: &'a [String],
    pub files_from: Option<&'a PathBuf>,
    /// cr-ecm6-4: the list's content, when the caller has read the file
    /// already — `Ok` the text, `Err` why it could not be read. Then THAT
    /// is the list, and `files_from` is not opened again: a front end
    /// reads the list once, before it asks anything, for the job's record
    /// (review cr-jl5-1), and the run must use what the record holds. Read
    /// again when the filter was built, after the question, a list changed
    /// meanwhile from `first.txt` to `second.txt` made the mirror copy
    /// `second.txt` while its saved job replayed `first.txt`. `None`: the
    /// file named by `files_from` is read here.
    pub files_from_read: Option<std::result::Result<&'a str, &'a str>>,
    /// ssc-6: an in-memory exact-path set (the previous pass's failed
    /// files) that overrides `files_from` for a retry pass. Never set by
    /// a CLI flag — the orchestrator threads it between passes.
    pub retry_only: Option<&'a std::collections::HashSet<PathBuf>>,
    /// JOB_LOGS review cr-jl4fix1-2: retry entries named by their exact
    /// bytes (`/`-separated) — names that are not UTF-8 — kept as bytes so
    /// any host can send them; only a host that holds such names turns them
    /// into its own paths.
    pub retry_only_raw: Option<&'a std::collections::HashSet<Vec<u8>>>,
    /// audit-19: the source root when the source is local. An absolute
    /// `--exclude` under it is made source-relative before use (see
    /// [`resolve_excludes`]); `None` for a remote source, where no
    /// absolute pattern can match.
    pub source_root: Option<&'a Path>,
    /// EXCLUDE_CASE_MATCHING (D-2026-11-20-1): `--ignore-case` — every
    /// `include` and `exclude` pattern ignores case, on the source walk and
    /// in a mirror's deletion scope alike. Never the `files_from` list.
    pub ignore_case: bool,
    pub min_size: Option<&'a str>,
    pub max_size: Option<&'a str>,
    pub min_age: Option<&'a str>,
    pub max_age: Option<&'a str>,
    /// cr-ecm5-3: what `exclude` resolved to, when the caller has resolved
    /// it already ([`resolve_excludes`]) — then THAT is the filter, and
    /// nothing here reads the disk for it again. `None`: resolved on the
    /// spot, from `exclude` and `source_root`.
    ///
    /// A front end resolves once, before it warns or asks anything, and
    /// hands the same result to every use: resolving again at dispatch,
    /// after the question, could give another answer than the one shown.
    /// An absolute exclude through a source alias was displayed as
    /// `first/Keep`; the alias changed while the question was open, and
    /// the confirmed mirror copied `first/Keep`.
    pub resolved: Option<&'a ResolvedExcludes>,
}

/// The names of `inputs`' `--files-from` list, `None` when there is no
/// list: from the content the caller read already when it gave it
/// (cr-ecm6-4), else from the file. A list the caller could not read is
/// the same error the file would give, and the file is not tried again.
fn listed_names(inputs: &FilterInputs<'_>) -> Result<Option<std::collections::HashSet<PathBuf>>> {
    match (inputs.files_from_read, inputs.files_from) {
        (Some(Ok(text)), _) => Ok(Some(FileFilter::files_from_text(text))),
        (Some(Err(why)), _) => Err(eyre!("opening files-from list {why}")),
        (None, Some(path)) => Ok(Some(FileFilter::load_files_from(path)?)),
        (None, None) => Ok(None),
    }
}

/// The exclude patterns `inputs` describe: the caller's own resolution
/// when it gave one (cr-ecm5-3), else resolved here.
fn resolved_patterns(inputs: &FilterInputs<'_>) -> Vec<String> {
    match inputs.resolved {
        Some(resolved) => resolved.patterns.clone(),
        None => resolve_excludes(inputs.exclude, inputs.source_root).patterns,
    }
}

/// Build a `FileFilter` from filter inputs. Used by every command
/// (copy/mirror/move/check) so filter behavior is identical
/// regardless of which CLI verb invoked it. The transfer-side
/// helper — not the leaf code — is what calculates the filter.
///
/// Validates glob patterns at construction time and surfaces
/// malformed globs with a `--include`/`--exclude` pointer (R58-F12).
pub fn build(inputs: &FilterInputs<'_>) -> Result<FileFilter> {
    let mut filter = FileFilter::default();
    // cr-ecm6-1: in the one form an include has — the form a peer is
    // sent — so that this filter and the peer's read the same pattern.
    filter.include_files = wire_includes(inputs.include, cfg!(windows));
    filter.exclude_files = resolved_patterns(inputs);
    filter.ignore_case = inputs.ignore_case;
    if let Some(s) = inputs.min_size {
        filter.min_size = Some(parse_size(s).with_context(|| format!("--min-size {s}"))?);
    }
    if let Some(s) = inputs.max_size {
        filter.max_size = Some(parse_size(s).with_context(|| format!("--max-size {s}"))?);
    }
    if let Some(s) = inputs.min_age {
        filter.min_age = Some(parse_duration(s).with_context(|| format!("--min-age {s}"))?);
    }
    if let Some(s) = inputs.max_age {
        filter.max_age = Some(parse_duration(s).with_context(|| format!("--max-age {s}"))?);
    }
    if filter.min_age.is_some() || filter.max_age.is_some() {
        // Captured once per command invocation — calculated by transfer-side
        // helper, not by leaf code each time `allows_entry` is called.
        filter.reference_time = Some(SystemTime::now());
    }
    if let Some(listed) = listed_names(inputs)? {
        filter.files_from = Some(listed);
    }
    if let Some(set) = inputs.retry_only {
        filter.files_from = Some(set.clone());
    }
    if let Some(raw) = inputs.retry_only_raw {
        let listed = filter.files_from.get_or_insert_with(Default::default);
        listed.extend(raw.iter().filter_map(|raw| {
            crate::raw_name::path_from_received_raw(
                raw,
                crate::raw_name::destination_can_store_raw_names(),
            )
        }));
    }
    // R58-F12: validate glob patterns at filter-construction
    // time. The runtime build_globset silently drops invalid
    // patterns (which is OK as a defense-in-depth fallback for
    // corrupted profiles), but at this layer we want to reject
    // malformed globs up front with a pointer to the bad
    // pattern. Operation-spec normalization already validates on
    // the remote-pull path; this closes the symmetry gap for
    // local / push paths.
    filter
        .validate_globs()
        .map_err(|msg| eyre!("invalid filter pattern: {msg}"))?;
    Ok(filter)
}

/// EXCLUDE_CASE_MATCHING slice 2 (AC-3, AC-5, AC-9): the one line a front
/// end shows when a run's patterns are read exactly as typed and nobody
/// said so — `"*Cache" matches Cache only; capital letters matter
/// (--ignore-case would also match cache, CACHE).` — or `None` when no
/// pattern's reading depends on case. Built from the first such pattern,
/// excludes before includes; the others are counted. WHEN to show it is
/// the front end's: not with a case mode stated, and not when the operator
/// has waived the question.
///
/// Slice 3b (AC-8): each pattern comes with the pattern file it was read
/// from, `None` for one typed on the command line, and the line says
/// which the operator did not type: `and 2 more patterns (from skip.txt)
/// match only as typed`.
///
/// cr-ecm4-3: the line is derived from the EFFECTIVE filter — `resolved`,
/// what [`resolve_excludes`] made of these same excludes:
/// - an exclude it reported as unable to match anything is passed over,
///   neither shown nor counted (the run has just said it matches nothing;
///   the line then said it "matches … only");
/// - an absolute exclude is echoed as typed and described as the pattern
///   it became below the source, so the source's own path is never shown
///   in another case (`/srv/Data` under `/srv` matches `Data`, and the
///   option would also match `data`, `DATA` — never `/SRV/DATA`).
pub fn case_note(
    exclude: &[(&str, Option<&str>)],
    include: &[(&str, Option<&str>)],
    resolved: &ResolvedExcludes,
) -> Option<String> {
    case_note_on(exclude, include, resolved, cfg!(windows))
}

/// [`case_note`] under one platform's path rule (`windows`).
fn case_note_on(
    exclude: &[(&str, Option<&str>)],
    include: &[(&str, Option<&str>)],
    resolved: &ResolvedExcludes,
    windows: bool,
) -> Option<String> {
    use crate::case_fold::Noted;
    let mut noted: Vec<Noted> = Vec::with_capacity(exclude.len() + include.len());
    for (at, &(typed, file)) in exclude.iter().enumerate() {
        if resolved.unmatchable.iter().any(|pattern| pattern == typed) {
            continue;
        }
        // What an absolute exclude became (the first of them, when the
        // entry it names is stored under several names), without the
        // `./` that anchors it at the source: that is how it is written
        // for the matcher, not part of what it names.
        let became = resolved
            .became
            .get(at)
            .and_then(|span| resolved.patterns.get(span.start))
            .filter(|_| is_absolute_pattern(typed, windows))
            .map(|pattern| pattern.strip_prefix("./").unwrap_or(pattern));
        noted.push(Noted {
            typed,
            read_as: became.unwrap_or(typed),
            file,
        });
    }
    noted.extend(include.iter().map(|&(typed, file)| Noted {
        typed,
        read_as: typed,
        file,
    }));
    crate::case_fold::case_note_of(&noted, windows)
}

/// Everything about a filter that can be refused from the command's own
/// words, checked without building it: the patterns, exactly as [`build`]
/// and [`build_spec`] validate them (the same resolved excludes, the same
/// case mode), and the sizes and ages. It reads no list file.
///
/// EXCLUDE_CASE_MATCHING slice 1b (AC-10): a front end calls this BEFORE
/// it warns, asks or announces anything. The filter itself is built when
/// the route is dispatched, which is after a mirror's question — so a
/// pattern that could not be used was refused only once the operator had
/// agreed to the deletion, or, with nobody to answer, never: the run said
/// "Aborted." and exited 0.
pub fn validate(inputs: &FilterInputs<'_>) -> Result<()> {
    let mut probe = FileFilter::default();
    probe.include_files = wire_includes(inputs.include, cfg!(windows));
    probe.exclude_files = resolved_patterns(inputs);
    probe.ignore_case = inputs.ignore_case;
    probe
        .validate_globs()
        .map_err(|msg| eyre!("invalid filter pattern: {msg}"))?;
    for (flag, size) in [
        ("--min-size", inputs.min_size),
        ("--max-size", inputs.max_size),
    ] {
        if let Some(s) = size {
            parse_size(s).with_context(|| format!("{flag} {s}"))?;
        }
    }
    for (flag, age) in [("--min-age", inputs.min_age), ("--max-age", inputs.max_age)] {
        if let Some(s) = age {
            parse_duration(s).with_context(|| format!("{flag} {s}"))?;
        }
    }
    Ok(())
}

/// Build the wire-side `FilterSpec` proto message from the same
/// filter inputs. Used by the remote push path so the daemon
/// enforces the same filter the CLI would have applied locally.
/// `--files-from` is read here and shipped expanded so the daemon
/// doesn't have to reach back into the client's filesystem.
pub fn build_spec(inputs: &FilterInputs<'_>) -> Result<crate::generated::FilterSpec> {
