/// `TransferArgs` stays in `blit-cli`). Inlined wrapper keeps the
/// `build_filter` / `build_filter_spec` call sites readable.
fn filter_inputs<'a>(args: &'a TransferArgs, source_root: Option<&'a Path>) -> FilterInputs<'a> {
