  501 fn case_note(args: &TransferArgs, resolved: &filter::ResolvedExcludes) -> Option<String> {
  502     if args.ignore_case || args.match_case || args.yes {
  503         return None;
  504     }
  508     if args.files_from.is_some() || args.retry_only.is_some() || args.retry_only_raw.is_some() {
  509         return None;
  510     }
  512     let origin = |origins: &[Option<PathBuf>], at: usize| {
  513         origins
  514             .get(at)
  515             .and_then(Option::as_ref)
  516             .map(|file| file.display().to_string())
  517     };
  518     let with_origins = |patterns: &[String], origins: &[Option<PathBuf>]| -> Vec<Option<String>> {
  519         (0..patterns.len()).map(|at| origin(origins, at)).collect()
  520     };
  521     let exclude_files = with_origins(&args.exclude, &args.exclude_origin);
  522     let include_files = with_origins(&args.include, &args.include_origin);
  523     fn paired<'a>(
  524         patterns: &'a [String],
  525         files: &'a [Option<String>],
  526     ) -> Vec<(&'a str, Option<&'a str>)> {
  527         patterns
  528             .iter()
  529             .map(String::as_str)
  530             .zip(files.iter().map(Option::as_deref))
  531             .collect()
  532     }
  533     filter::case_note(
  534         &paired(&args.exclude, &exclude_files),
  535         &paired(&args.include, &include_files),
  536         resolved,
  537     )
  538 }
