#[test]
fn mirror_ignore_case_reads_the_pattern_the_same_for_the_copy_and_the_delete() {
    let tmp = tempdir().unwrap();
    let (src, dst) = trees(tmp.path());
    let (code, out, err) = blit(&[
        "mirror",
        "--yes",
        "--ignore-case",
        "--exclude",
        "*cache",
        &with_slash(&src),
