            .with_context(|| format!("invalid compare_mode {}", spec.compare_mode))?;
        let mirror_mode = mirror_mode_from_proto(spec.mirror_mode)
            .with_context(|| format!("invalid mirror_mode {}", spec.mirror_mode))?;
