use blit_core::generated::{FilterSpec, MirrorMode, TransferOperationSpec};
use blit_core::mirror_planner::MirrorPlanner;
use blit_core::remote::transfer::operation_spec::{
    NormalizedTransferOperation, SUPPORTED_SPEC_VERSION,
};
use std::collections::HashSet;
use std::path::Path;

#[test]
fn received_exact_list_and_manifest() {
    let tmp = tempfile::tempdir().unwrap();
    let dst = tmp.path();
    let nested = "sub/name.txt";
    let flat = r"sub\name.txt";
    std::fs::create_dir(dst.join("sub")).unwrap();
    std::fs::write(dst.join(nested), b"nested").unwrap();
    std::fs::write(dst.join(flat), b"unrelated").unwrap();
    for wire_spelling in [flat, nested] {
        let op = NormalizedTransferOperation::from_spec(TransferOperationSpec {
            spec_version: SUPPORTED_SPEC_VERSION,
            filter: Some(FilterSpec {
                files_from_set: true,
                files_from: vec![wire_spelling.to_owned()],
                ..Default::default()
            }),
            mirror_mode: MirrorMode::FilteredSubset as i32,
            ..Default::default()
        }).unwrap();
        let filter = op.filter.unwrap();
        let manifest = HashSet::from([nested.to_owned()]);
        let plan = MirrorPlanner::new(false)
            .plan_session_deletions(dst, &manifest, &[], &HashSet::new(), true, &filter)
            .unwrap();
        println!("wire={wire_spelling:?}; allows nested={}; deletes flat={}",
            filter.allows_entry(Some(Path::new(nested)), &dst.join(nested), 6, None),
            plan.files.contains(&dst.join(flat)));
        assert_eq!(plan.files.contains(&dst.join(flat)), wire_spelling == flat);
    }
}
